/// The shells a script can be written for.
pub const SHELLS: &[&str] = &["bash", "zsh", "fish"];

/// `uniwidged completions <shell>` — prints the script.
///
/// ```sh
/// uniwidged completions bash > ~/.local/share/bash-completion/completions/uniwidged
/// uniwidged completions zsh  > ~/.zfunc/_uniwidged
/// uniwidged completions fish > ~/.config/fish/completions/uniwidged.fish
/// ```
pub fn command(args: &[String]) -> Result<(), String> {
    let shell = args
        .first()
        .ok_or("which shell? `uniwidged completions bash|zsh|fish`")?;
    let script = match shell.as_str() {
        "bash" => bash(),
        "zsh" => zsh(),
        "fish" => fish(),
        other => {
            return Err(format!(
                "`{other}` is not a shell this can write for; try one of {}",
                SHELLS.join(", ")
            ));
        }
    };
    print!("{script}");
    Ok(())
}

/// The words every command completes after its positional argument.
fn flags_of(command: &Command) -> Vec<&'static str> {
    let mut flags: Vec<&str> = command.flags.to_vec();
    flags.push("--config");
    flags
}

/// A bash script: one function, dispatching on the second word.
///
/// Written against `complete -F` and `COMPREPLY` alone — no
/// `bash-completion` helpers — so it works on a machine that has bash and
/// nothing else, which is what a `.deb`'s `Depends` promises.
pub fn bash() -> String {
    let names: Vec<&str> = COMMANDS.iter().map(|c| c.name).collect();
    let mut out = String::new();
    out.push_str(
        "# bash completion for uniwidged. Generated by `uniwidged completions bash`;\n\
         # regenerate rather than edit.\n\
         _uniwidged() {\n\
         \x20   local cur prev cmd\n\
         \x20   COMPREPLY=()\n\
         \x20   cur=\"${COMP_WORDS[COMP_CWORD]}\"\n\
         \x20   prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n\
         \x20   cmd=\"${COMP_WORDS[1]}\"\n\
         \x20   if [ \"$COMP_CWORD\" -eq 1 ]; then\n",
    );
    out.push_str(&format!(
        "        COMPREPLY=( $(compgen -W \"{} --version --help\" -- \"$cur\") )\n\
         \x20       return 0\n\
         \x20   fi\n\
         \x20   case \"$prev\" in\n\
         \x20       --config|--dir|--sdk|--key|--out|-o)\n\
         \x20           COMPREPLY=( $(compgen -f -- \"$cur\") )\n\
         \x20           return 0 ;;\n\
         \x20       --registry)\n\
         \x20           COMPREPLY=( $(compgen -W \"$(uniwidged registry list --names 2>/dev/null)\" -- \"$cur\") )\n\
         \x20           return 0 ;;\n\
         \x20   esac\n\
         \x20   case \"$cmd\" in\n",
        names.join(" ")
    ));
    for command in COMMANDS {
        let flags = flags_of(command).join(" ");
        let positional = match command.takes {
            Takes::Nothing | Takes::Key => String::new(),
            Takes::Widget => {
                "$(uniwidged list --names --config \"$(_uniwidged_config)\" 2>/dev/null) ".into()
            }
            Takes::Component => String::new(),
            Takes::Subcommand(words) => format!("{} ", words.join(" ")),
            Takes::Shell => format!("{} ", SHELLS.join(" ")),
        };
        out.push_str(&format!("        {})\n", command.name));
        if command.takes == Takes::Component {
            // Files first: a `.wasm` is what the command is about, and the
            // flags are what goes after it.
            out.push_str(
                "            COMPREPLY=( $(compgen -f -X '!*.wasm' -- \"$cur\") \
                 $(compgen -d -- \"$cur\") )\n",
            );
            out.push_str(&format!(
                "            case \"$cur\" in -*) COMPREPLY=( $(compgen -W \"{flags}\" -- \"$cur\") ) ;; esac\n"
            ));
        } else {
            out.push_str(&format!(
                "            COMPREPLY=( $(compgen -W \"{positional}{flags}\" -- \"$cur\") )\n"
            ));
        }
        out.push_str("            return 0 ;;\n");
    }
    out.push_str(
        "    esac\n\
         }\n\
         # The `--config` the user is typing, so that widget names complete\n\
         # from the same file the command will read.\n\
         _uniwidged_config() {\n\
         \x20   local i\n\
         \x20   for ((i = 1; i < ${#COMP_WORDS[@]} - 1; i++)); do\n\
         \x20       if [ \"${COMP_WORDS[i]}\" = \"--config\" ]; then\n\
         \x20           printf '%s' \"${COMP_WORDS[i+1]}\"\n\
         \x20           return\n\
         \x20       fi\n\
         \x20   done\n\
         \x20   printf '%s' \"${UNIWIDGED_CONFIG:-}\"\n\
         }\n\
         complete -F _uniwidged uniwidged\n",
    );
    out
}

/// A zsh script, in the `#compdef` form `fpath` loads.
pub fn zsh() -> String {
    let mut out = String::new();
    out.push_str(
        "#compdef uniwidged\n\
         # zsh completion for uniwidged. Generated by `uniwidged completions zsh`;\n\
         # regenerate rather than edit.\n\
         _uniwidged() {\n\
         \x20   local -a commands\n\
         \x20   commands=(\n",
    );
    for command in COMMANDS {
        out.push_str(&format!(
            "        '{}:{}'\n",
            command.name,
            command.summary.replace('\'', "'\\''").replace(':', "\\:")
        ));
    }
    out.push_str(
        "    )\n\
         \x20   if (( CURRENT == 2 )); then\n\
         \x20       _describe -t commands 'uniwidged command' commands\n\
         \x20       return\n\
         \x20   fi\n\
         \x20   local -a widgets flags\n\
         \x20   case \"${words[2]}\" in\n",
    );
    for command in COMMANDS {
        let flags: Vec<String> = flags_of(command).iter().map(|f| format!("'{f}'")).collect();
        out.push_str(&format!("        {})\n", command.name));
        out.push_str(&format!("            flags=({})\n", flags.join(" ")));
        match command.takes {
            Takes::Widget => out.push_str(
                "            widgets=(${(f)\"$(uniwidged list --names 2>/dev/null)\"})\n\
                 \x20           _alternative 'widgets:installed widget:(${widgets})' 'flags:flag:(${flags})'\n",
            ),
            Takes::Component => out.push_str(
                "            _alternative 'files:component:_files -g \"*.wasm\"' 'flags:flag:(${flags})'\n",
            ),
            Takes::Subcommand(words) => out.push_str(&format!(
                "            _alternative 'subcommands:subcommand:({})' 'flags:flag:(${{flags}})'\n",
                words.join(" ")
            )),
            Takes::Shell => out.push_str(&format!(
                "            _alternative 'shells:shell:({})'\n",
                SHELLS.join(" ")
            )),
            Takes::Nothing | Takes::Key => {
                out.push_str("            _alternative 'flags:flag:(${flags})'\n")
            }
        }
        out.push_str("            ;;\n");
    }
    out.push_str(
        "    esac\n\
         }\n\
         _uniwidged \"$@\"\n",
    );
    out
}

/// A fish script: one `complete` line per fact.
pub fn fish() -> String {
    let mut out = String::new();
    out.push_str(
        "# fish completion for uniwidged. Generated by `uniwidged completions fish`;\n\
         # regenerate rather than edit.\n\
         complete -c uniwidged -f\n",
    );
    for command in COMMANDS {
        out.push_str(&format!(
            "complete -c uniwidged -n __fish_use_subcommand -a {} -d '{}'\n",
            command.name,
            command.summary.replace('\'', "\\'")
        ));
    }
    for command in COMMANDS {
        let seen = format!("__fish_seen_subcommand_from {}", command.name);
        match command.takes {
            Takes::Widget => out.push_str(&format!(
                "complete -c uniwidged -n '{seen}' -a '(uniwidged list --names 2>/dev/null)'\n"
            )),
            Takes::Component => out.push_str(&format!(
                "complete -c uniwidged -n '{seen}' -F -a '(__fish_complete_suffix .wasm)'\n"
            )),
            Takes::Subcommand(words) => out.push_str(&format!(
                "complete -c uniwidged -n '{seen}' -a '{}'\n",
                words.join(" ")
            )),
            Takes::Shell => out.push_str(&format!(
                "complete -c uniwidged -n '{seen}' -a '{}'\n",
                SHELLS.join(" ")
            )),
            Takes::Nothing | Takes::Key => {}
        }
        for flag in flags_of(command) {
            let (short, long) = if let Some(long) = flag.strip_prefix("--") {
                (String::new(), format!(" -l {long}"))
            } else {
                (format!(" -s {}", &flag[1..]), String::new())
            };
            let takes_file = matches!(
                flag,
                "--config" | "--dir" | "--sdk" | "--key" | "--out" | "-o"
            );
            out.push_str(&format!(
                "complete -c uniwidged -n '{seen}'{short}{long}{}\n",
                if takes_file { " -r -F" } else { "" }
            ));
        }
    }
    out
}

